from __future__ import annotations

import os


class KVStoreError(Exception):
    """Base class for all kvstore errors."""


class RecordError(KVStoreError):
    """A record could not be decoded."""


class IncompleteRecordError(RecordError):
    """Not enough bytes are available for the record."""


class CorruptRecordError(RecordError):
    """The record bytes are present but wrong."""


class CorruptSegmentError(KVStoreError):
    """A segment file contains a corrupt record."""

    def __init__(self, path: str | os.PathLike, offset: int, reason: str) -> None:
        import pathlib

        self.path = pathlib.Path(path)
        self.offset = offset
        self.reason = reason
        super().__init__(f"corrupt segment {self.path.name} at offset {offset}: {reason}")

"""One append-only segment file."""
from __future__ import annotations

import os
import pathlib
from typing import Iterator

from .errors import CorruptRecordError, CorruptSegmentError, IncompleteRecordError
from .record import decode_record


class Segment:
    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = seg_id
        self._fh = open(self._path, "a+b")

    @property
    def path(self) -> pathlib.Path:
        return self._path

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def size(self) -> int:
        self._fh.flush()
        return os.path.getsize(self._path)

    def append(self, blob: bytes) -> int:
        """Append ``blob`` at the end of the file; return its offset."""
        offset = self.size
        self._fh.seek(0, os.SEEK_END)
        self._fh.write(blob)
        self._fh.flush()
        return offset

    def read_record(self, offset: int) -> tuple[str, str | None, int]:
        """Decode the record stored at ``offset``."""
        data = self._read_all()
        try:
            return decode_record(data, offset)
        except (CorruptRecordError, IncompleteRecordError) as exc:
            raise CorruptSegmentError(self._path, offset, str(exc)) from exc

    def _read_all(self) -> bytes:
        self._fh.flush()
        self._fh.seek(0)
        return self._fh.read()

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        """Yield (key, value, offset); stop silently at a truncated tail."""
        data = self._read_all()
        offset = 0
        while offset < len(data):
            try:
                key, value, total = decode_record(data, offset)
            except IncompleteRecordError:
                return
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from exc
            yield key, value, offset
            offset += total

    def close(self) -> None:
        if not self._fh.closed:
            self._fh.close()

"""In-memory index: key -> newest record location."""
from __future__ import annotations

import dataclasses


@dataclasses.dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        entry = self._entries.get(key)
        if entry is None or entry[1]:
            return None
        return entry[0]

    def live_keys(self) -> list[str]:
        live = [(loc.seg_id, loc.offset, k)
                for k, (loc, tomb) in self._entries.items() if not tomb]
        live.sort()
        return [k for _, _, k in live]

    def tombstone_count(self) -> int:
        return sum(1 for _, tomb in self._entries.values() if tomb)

    def __len__(self) -> int:
        return sum(1 for _, tomb in self._entries.values() if not tomb)

"""The KVStore."""
from __future__ import annotations

import os
import pathlib
import re
from typing import NamedTuple

from .index import Index, Location
from .record import MAX_KEY_LEN, encode_record
from .segment import Segment

SEGMENT_RE = re.compile(r"^\d{6}\.seg$")


class Stats(NamedTuple):
    live_keys: int
    tombstones: int
    total_records: int
    dead_records: int
    segment_count: int
    bytes_on_disk: int


def segment_name(seg_id: int) -> str:
    return f"{seg_id:06d}.seg"


def _check_key(key: object) -> None:
    if not isinstance(key, str):
        raise TypeError("key must be str")
    if not 1 <= len(key.encode("utf-8")) <= MAX_KEY_LEN:
        raise ValueError("key must be 1..65535 bytes when UTF-8 encoded")


class KVStore:
    def __init__(self, root: str | os.PathLike, *, max_segment_bytes: int = 4096) -> None:
        if (not isinstance(max_segment_bytes, int) or isinstance(max_segment_bytes, bool)
                or max_segment_bytes < 16):
            raise ValueError("max_segment_bytes must be an int >= 16")
        self._max = max_segment_bytes
        self._root = pathlib.Path(root)
        self._root.mkdir(parents=True, exist_ok=True)
        self._index = Index()
        self._segments: dict[int, Segment] = {}
        self._total = 0
        self._closed = False
        self._recover()

    def _recover(self) -> None:
        ids = sorted(int(p.name[:6]) for p in self._root.iterdir()
                     if SEGMENT_RE.match(p.name) and p.is_file())
        try:
            for seg_id in ids:
                seg = Segment(self._root / segment_name(seg_id), seg_id)
                self._segments[seg_id] = seg
                for key, value, offset in seg.scan():
                    self._index.put(key, Location(seg_id, offset), tombstone=value is None)
                    self._total += 1
        except BaseException:
            self._close_segments()
            raise
        if not ids:
            self._segments[1] = Segment(self._root / segment_name(1), 1)

    def _close_segments(self) -> None:
        for seg in self._segments.values():
            seg.close()

    @property
    def root(self) -> pathlib.Path:
        return self._root

    def _check_open(self) -> None:
        if self._closed:
            raise ValueError("store is closed")

    def _active(self) -> Segment:
        return self._segments[max(self._segments)]

    def _write(self, key: str, value: str | None) -> None:
        blob = encode_record(key, value)
        active = self._active()
        if active.size > 0 and active.size + len(blob) > self._max:
            active = Segment(self._root / segment_name(active.seg_id + 1), active.seg_id + 1)
            self._segments[active.seg_id] = active
        offset = active.append(blob)
        self._index.put(key, Location(active.seg_id, offset), tombstone=value is None)
        self._total += 1

    def set(self, key: str, value: str) -> None:
        self._check_open()
        _check_key(key)
        if not isinstance(value, str):
            raise TypeError("value must be str")
        value.encode("utf-8")
        self._write(key, value)

    def get(self, key: str) -> str | None:
        self._check_open()
        _check_key(key)
        loc = self._index.get(key)
        if loc is None:
            return None
        return self._segments[loc.seg_id].read_record(loc.offset)[1]

    def delete(self, key: str) -> bool:
        self._check_open()
        _check_key(key)
        if self._index.get(key) is None:
            return False
        self._write(key, None)
        return True

    def keys(self) -> list[str]:
        self._check_open()
        return self._index.live_keys()

    def stats(self) -> Stats:
        self._check_open()
        live = len(self._index)
        tombs = self._index.tombstone_count()
        size = sum(seg.size for seg in self._segments.values())
        return Stats(live, tombs, self._total, self._total - live - tombs,
                     len(self._segments), size)

    def close(self) -> None:
        if not self._closed:
            self._close_segments()
            self._closed = True

    def __enter__(self) -> "KVStore":
        self._check_open()
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

"""Command line interface: python -m kvstore ROOT COMMAND [ARGS...]."""
from __future__ import annotations

import argparse
import sys

from .compact import compact
from .errors import CorruptSegmentError
from .store import KVStore


def _positive_int(text: str) -> int:
    try:
        value = int(text)
    except ValueError:
        raise argparse.ArgumentTypeError(f"not a positive integer: {text!r}") from None
    if value <= 0:
        raise argparse.ArgumentTypeError(f"not a positive integer: {text!r}")
    return value


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="kvstore")
    parser.add_argument("--max-segment-bytes", type=_positive_int, default=4096)
    parser.add_argument("root")
    sub = parser.add_subparsers(dest="command", required=True)
    for name, nargs in (("set", 2), ("get", 1), ("delete", 1), ("list", 0),
                        ("compact", 0), ("stats", 0)):
        p = sub.add_parser(name)
        if nargs >= 1:
            p.add_argument("key")
        if nargs == 2:
            p.add_argument("value")
    return parser


def _run(store: KVStore, args: argparse.Namespace) -> int:
    cmd = args.command
    if cmd == "set":
        store.set(args.key, args.value)
    elif cmd == "get":
        value = store.get(args.key)
        if value is None:
            return 1
        sys.stdout.write(value + "\n")
    elif cmd == "delete":
        return 0 if store.delete(args.key) else 1
    elif cmd == "list":
        for key in store.keys():
            sys.stdout.write(key + "\n")
    elif cmd == "compact":
        r = compact(store)
        sys.stdout.write(f"removed={r.segments_removed} written={r.records_written} "
                         f"dropped={r.records_dropped} reclaimed={r.bytes_reclaimed}\n")
    else:
        s = store.stats()
        sys.stdout.write(" ".join(f"{k}={v}" for k, v in s._asdict().items()) + "\n")
    return 0


def main(argv: list[str] | None = None) -> int:
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        with KVStore(args.root, max_segment_bytes=args.max_segment_bytes) as store:
            return _run(store, args)
    except (ValueError, TypeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except CorruptSegmentError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 3


if __name__ == "__main__":
    sys.exit(main())

